#!/usr/bin/env python3
"""Export the merge vertex degree figure using the existing publication data."""

import argparse
from pathlib import Path


METHODS = (
    ("random", "R", "mark=o"),
    ("high_degree", "HD", "mark=triangle"),
    ("kamada_kawai", "KK", "mark=square"),
    ("heuristic_outer_face", "OF-H", "mark=diamond,dashed"),
    ("exact_outer_face", "OF-B", "mark=triangle,mark options={rotate=180}"),
)


def export(paper: Path) -> None:
    destination = paper / "resources/evaluation"
    lines = [
        "% Generated by check/scripts/export_paper_merge_vertex_degrees.py.",
        r"\begingroup",
        r"\pgfplotslegendfromname{mergedegreelegend}\par\smallskip",
    ]
    for domain, title in (("pglib", "PGLib"), ("snd", "SNDlib")):
        if domain == "snd":
            lines.append(r"\hfill")
        lines.extend([
            r"\begin{subfigure}[t]{0.485\linewidth}",
            r"\centering",
            r"\begin{tikzpicture}",
            r"\begin{axis}[",
            r"  width=.97\linewidth,height=.5567\linewidth,",
            r"  axis lines*=left,axis line style={line width=.5pt},",
            r"  xmin=.5,xmax=17.5,ymin=-.015,ymax=.78,",
            r"  xtick={1,3,5,7,9,11,13,15,17},",
            r"  ytick={0,.2,.4,.6},yticklabels={0,20,40,60},",
            r"  tick label style={font=\scriptsize},label style={font=\scriptsize},",
            r"  ylabel={\shortstack{Selected merge\\vertices [\%]}},",
            r"  xlabel={Degree before the join},",
            r"  ymajorgrids=true,grid style={gray!20,line width=.3pt},",
            r"  legend columns=5,legend cell align=left,",
            r"  legend style={font=\scriptsize,draw=none,",
            r"    /tikz/every even column/.append style={column sep=3mm}},",
            r"  every axis plot/.append style={line width=.8pt,mark size=1.7pt},",
        ])
        if domain == "pglib":
            lines.append(r"  legend to name=mergedegreelegend,")
        lines.append("]")
        for index, (method, label, style) in enumerate(METHODS):
            data = f"resources/evaluation/plot-data/merge-node-degree-{domain}-{method}.dat"
            if not (paper / data).is_file():
                raise FileNotFoundError(paper / data)
            forget = ",forget plot" if domain == "snd" else ""
            lines.append(
                rf"\addplot+[color=pigMethod{index},{style}{forget}] "
                rf"table[x=degree,y=fraction] {{{data}}};"
            )
            if domain == "pglib":
                lines.append(rf"\addlegendentry{{{label}}}")
        lines.extend([
            r"\end{axis}",
            r"\end{tikzpicture}",
            rf"\caption{{{title}}}",
            r"\end{subfigure}",
        ])
    lines.extend([r"\endgroup", ""])
    (destination / "fig-app-merge-vertex-degrees.tikz").write_text("\n".join(lines))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("paper", type=Path)
    export(parser.parse_args().paper.resolve())
